from pathlib import Path
p=Path('index.html')
s=p.read_text()
repls=[]
repls.append(("function dayDetail(d,day){let ev=d.events.filter(e=>e.dayId===day.id).sort((a,b)=>new Date(a.at)-new Date(b.at)),sessions=day.spotSessions||[];show(`Angeltag ${date(day.startedAt)}`,`<p><b>${esc(waterName(d,day.waterId))}</b><br><span class=\"muted\">${time(day.startedAt)}${day.endedAt?' – '+time(day.endedAt):' · läuft'}</span></p>${weatherHTML(day.weather)}<div class=\"section\"><h2>Spot-Zeiten</h2></div>${sessions.map(s=>{let end=sessionEnd(day,s),running=!end&&!day.endedAt;return `<div class=\"row\"><div style=\"font-size:26px\">📍</div><div class=\"grow\"><b>${esc(spotLabel(d,s.spotId))}</b><div class=\"muted\">${time(s.startedAt)}${end?' – '+time(end):running?' · läuft':' · beendet'}</div></div><b>${sessionMinutes(day,s)} min</b></div>`}).join('')||'<div class=\"empty\">Keine Spot-Zeiten.</div>'}<div class=\"section\"><h2>Ereignisse</h2></div>${ev.map(e=>erow(e,d)).join('')||'<div class=\"empty\">Keine Ereignisse.</div>'}`);bindEvents(d)}",
"function dtLocal(v){if(!v)return '';let d=new Date(v),z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`}\nfunction dayEditForm(d,day){let running=!day.endedAt;show('Angeltag bearbeiten',`<form id=\"dayEdit\" class=\"form\"><div class=\"notice\">Korrekturfunktion: Zeiten nur ändern, wenn die Aufzeichnung wirklich falsch ist.</div><div class=\"field\"><label>Gewässer</label><select name=\"waterId\" required>${d.waters.map(w=>`<option value=\"${w.id}\" ${w.id===day.waterId?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div>${field('startedAt','Start',dtLocal(day.startedAt),'datetime-local','required')}${running?'':field('endedAt','Ende',dtLocal(day.endedAt),'datetime-local','required')}${area('notes','Notizen',day.notes||'')}<button class=\"btn full\">Korrektur speichern</button></form>`);$('#dayEdit').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),start=new Date(f.get('startedAt')),end=running?null:new Date(f.get('endedAt'));if(Number.isNaN(start.getTime())||(!running&&Number.isNaN(end.getTime()))){alert('Bitte gültige Zeiten eingeben.');return}if(end&&end<start){alert('Das Ende kann nicht vor dem Start liegen.');return}day.waterId=f.get('waterId');day.startedAt=start.toISOString();if(end)day.endedAt=end.toISOString();day.notes=f.get('notes');for(const ss of day.spotSessions||[]){let se=ss.endedAt?new Date(ss.endedAt):null,st=new Date(ss.startedAt);if(st<start||(end&&st>end)||(se&&end&&se>end)){alert('Eine Spot-Zeit liegt außerhalb des Angeltags. Korrigiere zuerst die Spot-Zeit.');return}}await put('days',day);$('#modal').close();render()}}\nfunction spotSessionEditForm(d,day,sess){let ended=!!sessionEnd(day,sess);show('Spot-Zeit korrigieren',`<form id=\"sessionEdit\" class=\"form\"><div class=\"notice\">Nur zur Korrektur falscher Aufzeichnungen. Die normale Bedienung bleibt Spot starten / Spot beenden.</div><div class=\"field\"><label>Spot</label><select name=\"spotId\" required>${d.spots.filter(s=>s.waterId===day.waterId).map(s=>`<option value=\"${s.id}\" ${s.id===sess.spotId?'selected':''}>${esc(spotLabel(d,s.id))}</option>`).join('')}</select></div>${field('startedAt','Start',dtLocal(sess.startedAt),'datetime-local','required')}${ended?field('endedAt','Ende',dtLocal(sessionEnd(day,sess)),'datetime-local','required'):''}<button class=\"btn full\">Korrektur speichern</button></form>`);$('#sessionEdit').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),start=new Date(f.get('startedAt')),end=ended?new Date(f.get('endedAt')):null,ds=new Date(day.startedAt),de=day.endedAt?new Date(day.endedAt):null;if(Number.isNaN(start.getTime())||(end&&Number.isNaN(end.getTime()))){alert('Bitte gültige Zeiten eingeben.');return}if(start<ds||(de&&start>de)||(end&&end<start)||(end&&de&&end>de)){alert('Die Spot-Zeit muss innerhalb des Angeltags liegen.');return}let overlap=(day.spotSessions||[]).some(x=>x.id!==sess.id&&new Date(x.startedAt)<(end||new Date())&&new Date(sessionEnd(day,x)||new Date())>start);if(overlap){alert('Diese Korrektur würde sich mit einer anderen Spot-Zeit überschneiden.');return}sess.spotId=f.get('spotId');sess.startedAt=start.toISOString();if(end){sess.endedAt=end.toISOString();sess.durationMin=mins(sess.startedAt,sess.endedAt)}await put('days',day);$('#modal').close();render()}}\nfunction dayDetail(d,day){let ev=d.events.filter(e=>e.dayId===day.id).sort((a,b)=>new Date(a.at)-new Date(b.at)),sessions=day.spotSessions||[];show(`Angeltag ${date(day.startedAt)}`,`<div class=\"section\" style=\"margin-top:0\"><div><b>${esc(waterName(d,day.waterId))}</b><br><span class=\"muted\">${time(day.startedAt)}${day.endedAt?' – '+time(day.endedAt):' · läuft'}</span></div><button class=\"link\" id=\"editDay\">Bearbeiten</button></div>${day.notes?`<p>${esc(day.notes)}</p>`:''}${weatherHTML(day.weather)}<div class=\"section\"><h2>Spot-Zeiten</h2></div>${sessions.map(s=>{let end=sessionEnd(day,s),running=!end&&!day.endedAt;return `<button class=\"row\" data-session=\"${s.id}\"><div style=\"font-size:26px\">📍</div><div class=\"grow\"><b>${esc(spotLabel(d,s.spotId))}</b><div class=\"muted\">${time(s.startedAt)}${end?' – '+time(end):running?' · läuft':' · beendet'} · antippen zum Korrigieren</div></div><b>${sessionMinutes(day,s)} min</b></button>`}).join('')||'<div class=\"empty\">Keine Spot-Zeiten.</div>'}<div class=\"section\"><h2>Ereignisse</h2></div>${ev.map(e=>erow(e,d)).join('')||'<div class=\"empty\">Keine Ereignisse.</div>'}`);$('#editDay').onclick=()=>dayEditForm(d,day);$$('[data-session]').forEach(b=>b.onclick=()=>spotSessionEditForm(d,day,sessions.find(s=>s.id===b.dataset.session)));bindEvents(d)}"))
for old,new in repls:
    if s.count(old)!=1: raise SystemExit(f'guard failed: expected exactly one target, got {s.count(old)}')
    s=s.replace(old,new)
p.write_text(s)
print('v0.5 editing patch applied')
